// Parse Twilio voice webhook payload
const body = $input.item.json.body;

// Twilio sends form data, parse it
let callData = {
  callSid: body.CallSid,
  callerNumber: body.From,
  calledNumber: body.To,
  callStatus: body.CallStatus,
  direction: body.Direction || 'inbound',

  // Geographic info
  fromCity: body.FromCity,
  fromState: body.FromState,
  fromCountry: body.FromCountry,

  // Speech recognition (if available)
  speechResult: body.SpeechResult,
  confidence: body.Confidence ? parseFloat(body.Confidence) : null,

  // Digit input (DTMF)
  digits: body.Digits,

  // Recording info
  recordingUrl: body.RecordingUrl,
  recordingSid: body.RecordingSid,

  // Call tracking
  isInitialCall: !body.SpeechResult && !body.Digits,
  timestamp: new Date().toISOString()
};

return { json: callData };

// Merge call data with hotel config
const call = $('Parse Call Data').item.json;
const hotel = $input.item.json;

return {
  json: {
    ...call,
    hotelId: hotel.id,
    hotelName: hotel.name,
    staffPhone: hotel.staff_phone_number,
    confidenceThreshold: parseFloat(hotel.confidence_threshold) || 0.75,
    telegramBotToken: hotel.telegram_bot_token,
    telegramChatId: hotel.telegram_chat_id,
    twilioAccountSid: hotel.twilio_account_sid,
    twilioAuthToken: hotel.twilio_auth_token
  }
};

// Generate TwiML for initial greeting in 3 languages
const hotel = $input.item.json;

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Gather input="speech" language="sq-AL" speechTimeout="3" action="/webhook/twilio-voice-webhook" method="POST">
    <Say language="sq-AL" voice="Google.sq-AL-Standard-A">
      Mirësevini në ${hotel.hotelName}. Si mund t'ju ndihmojmë sot?
    </Say>
    <Pause length="1"/>
    <Say language="en-US" voice="Google.en-US-Standard-C">
      Welcome to ${hotel.hotelName}. How can we help you today?
    </Say>
    <Pause length="1"/>
    <Say language="it-IT" voice="Google.it-IT-Standard-A">
      Benvenuti a ${hotel.hotelName}. Come possiamo aiutarvi oggi?
    </Say>
  </Gather>
  <Say language="en-US">We didn't receive any input. Please call again.</Say>
  <Hangup/>
</Response>`;

return {
  json: {
    ...hotel,
    twimlResponse: twiml
  }
};

// Parse AI analysis and determine action
const context = $('Merge Call & Config').item.json;
const aiResponse = $input.item.json.message?.content || $input.item.json;

let analysis;
try {
  analysis = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
} catch (e) {
  analysis = {
    language: 'en',
    intent: 'unknown',
    confidence: 0.5,
    is_complex: true,
    wants_human: false,
    response_text: 'I\'m sorry, I didn\'t understand. Let me transfer you to our reception.'
  };
}

const confidenceThreshold = context.confidenceThreshold || 0.75;
const needsTransfer = 
  analysis.confidence < confidenceThreshold ||
  analysis.is_complex === true ||
  analysis.wants_human === true ||
  ['complaint', 'refund_request', 'human_request', 'booking_modification',
   'special_pricing', 'group_reservation', 'unknown'].includes(analysis.intent);

// Transfer messages
const transferMessages = {
  sq: 'Po ju transferoj tek recepsioni. Ju lutem prisni.',
  en: 'I am transferring you to our reception. Please hold.',
  it: 'La sto trasferendo alla reception. Attendere prego.'
};

// Determine voice
const voices = {
  sq: 'Google.sq-AL-Standard-A',
  en: 'Google.en-US-Standard-C',
  it: 'Google.it-IT-Standard-A'
};

const lang = analysis.language || 'en';

return {
  json: {
    ...context,
    speechResult: context.speechResult,
    detectedLanguage: lang,
    intent: analysis.intent,
    confidence: analysis.confidence,
    isComplex: analysis.is_complex,
    wantsHuman: analysis.wants_human,
    responseText: analysis.response_text,
    needsTransfer: needsTransfer,
    transferMessage: transferMessages[lang] || transferMessages.en,
    voice: voices[lang] || voices.en,
    languageCode: lang === 'sq' ? 'sq-AL' : lang === 'it' ? 'it-IT' : 'en-US'
  }
};

// Generate TwiML for AI response with follow-up
const data = $input.item.json;

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say language="${data.languageCode}" voice="${data.voice}">
    ${data.responseText}
  </Say>
  <Pause length="1"/>
  <Gather input="speech" language="${data.languageCode}" speechTimeout="3" action="/webhook/twilio-voice-webhook" method="POST">
    <Say language="${data.languageCode}" voice="${data.voice}">
      ${data.detectedLanguage === 'sq' ? 'A ka diçka tjetër që dëshironi të dini?' : 
        data.detectedLanguage === 'it' ? 'C\'è qualcos\'altro che vorrebbe sapere?' : 
        'Is there anything else you would like to know?'}
    </Say>
  </Gather>
  <Say language="${data.languageCode}" voice="${data.voice}">
    ${data.detectedLanguage === 'sq' ? 'Faleminderit që na kontaktuat. Mirupafshim!' : 
      data.detectedLanguage === 'it' ? 'Grazie per averci contattato. Arrivederci!' : 
      'Thank you for calling. Goodbye!'}
  </Say>
  <Hangup/>
</Response>`;

return {
  json: {
    ...data,
    twimlResponse: twiml
  }
};

// Generate TwiML for transfer to human
const data = $input.item.json;

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say language="${data.languageCode}" voice="${data.voice}">
    ${data.transferMessage}
  </Say>
  <Dial timeout="30" callerId="${data.callerNumber}">
    <Number>${data.staffPhone}</Number>
  </Dial>
  <Say language="${data.languageCode}" voice="${data.voice}">
    ${data.detectedLanguage === 'sq' ? 'Na vjen keq, linja është e zënë. Ju lutem provoni përsëri më vonë ose dërgoni mesazh në WhatsApp.' : 
      data.detectedLanguage === 'it' ? 'Siamo spiacenti, la linea è occupata. Si prega di riprovare più tardi o di inviare un messaggio WhatsApp.' : 
      'We\'re sorry, the line is busy. Please try again later or send us a WhatsApp message.'}
  </Say>
  <Hangup/>
</Response>`;

return {
  json: {
    ...data,
    twimlResponse: twiml
  }
};

